using Harness.Core.Instructions;
using Harness.Infrastructure.Clients;
using Harness.Infrastructure.Git;

namespace Harness.Infrastructure.Hooks;

public sealed class GitHooks(string directory)
{
    public static IReadOnlyList<string> Names { get; } = ["post-commit", "post-checkout", "post-merge", "post-rewrite"];
    public static MarkedBlock Section { get; } =
        new(
            "# BEGIN harness hook (generated by 'harness hooks'; edit outside this block)",
            "# END harness hook",
            "harness hook"
        );
    public string DirectoryPath => directory;

    public static async Task<GitHooks> ForAsync(GitRepository repository, CancellationToken token)
    {
        ArgumentNullException.ThrowIfNull(repository);
        var configured = await SetupQuery.QueryAsync(
            "git",
            ["-C", repository.Root, "config", "--get", "core.hooksPath"],
            token
        );
        return new(
            configured.Length is 0
                ? Path.Combine(repository.CommonDir, "hooks")
                : Path.GetFullPath(configured, repository.Root)
        );
    }

    public IReadOnlyList<FileChange> Status() =>
        Names
            .Select(name =>
            {
                var path = Path.Combine(directory, name);
                var source = File.Exists(path) ? FileEditor.Read(path) : "";
                return new FileChange(path, Section.Find(source).Start >= 0 ? "unchanged" : "absent", source, source);
            })
            .ToArray();

    public FileChange Set(string name, bool install, string command = "harness", bool dryRun = false)
    {
        if (!Names.Contains(name, StringComparer.Ordinal))
        {
            throw new ArgumentException("unknown Git hook", nameof(name));
        }
        if (command.IndexOfAny(['\r', '\n', '\0']) >= 0)
        {
            throw new ArgumentException("invalid hook executable", nameof(command));
        }
        var path = Path.Combine(directory, name);
        var refused = false;
        var change = FileEditor.Apply(
            path,
            (source, exists) =>
            {
                if (!install)
                {
                    return exists ? Section.Cut(source) : new(source, "absent");
                }
                var start = Section.Find(source).Start;
                if (exists && start < 0 && !Shell(source))
                {
                    refused = true;
                    return new(source, "refuse");
                }
                var newline = MarkedBlock.Newline(source);
                var prefix =
                    start >= 0
                    && !source.TrimStart('\uFEFF', ' ', '\t', '\r', '\n').StartsWith("#!", StringComparison.Ordinal)
                        ? "#!/bin/sh" + newline + newline
                        : "";
                var input = string.IsNullOrWhiteSpace(source) ? "#!/bin/sh" + newline : source;
                var edit = Section.Put(input, Block(command));
                return prefix.Length > 0 ? new(prefix + edit.Text, "update") : edit;
            },
            dryRun,
            empty: text => string.IsNullOrWhiteSpace(text) || text.Trim() is "#!/bin/sh"
        );
        if (install && change.Writes && !dryRun && !OperatingSystem.IsWindows())
        {
            var real = FileEditor.Resolve(path);
            File.SetUnixFileMode(
                real,
                File.GetUnixFileMode(real)
                    | UnixFileMode.UserExecute
                    | UnixFileMode.GroupExecute
                    | UnixFileMode.OtherExecute
            );
        }
        return refused
            ? change with
            {
                Reason = "existing hook is not a shell script; edit it by hand or replace it with a shell wrapper",
            }
            : change;
    }

    public static string Block(string command)
    {
        var quoted = "'" + command.Replace("'", "'\"'\"'", StringComparison.Ordinal) + "'";
        return Section.Begin
            + "\n(\n  if command -v "
            + quoted
            + " >/dev/null 2>&1; then\n    "
            + quoted
            + " sync >/dev/null 2>&1 </dev/null &\n  fi\n) >/dev/null 2>&1 || true\n"
            + Section.End;
    }

    private static bool Shell(string source)
    {
        var trimmed = source.TrimStart('\uFEFF', ' ', '\t', '\r', '\n');
        return string.IsNullOrWhiteSpace(source)
            || new[]
            {
                "#!/bin/sh",
                "#!/usr/bin/env sh",
                "#!/bin/bash",
                "#!/usr/bin/env bash",
                "#!/bin/zsh",
                "#!/usr/bin/env zsh",
            }.Any(prefix => trimmed.StartsWith(prefix, StringComparison.Ordinal));
    }
}
